<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {api,put,post,csrf,type Profile} from '../api'
const emit=defineEmits<{signedOut:[message:string]}>()
const roleNames:Record<string,string>={ADMIN:'系统管理员',EMPLOYEE:'普通员工',MANAGER:'部门主管',BUYER:'采购专员',WAREHOUSE:'仓库管理员'}
const profile=ref<Profile|null>(null),name=ref(''),email=ref(''),phone=ref(''),currentPassword=ref(''),newPassword=ref(''),confirm=ref(''),busy=ref(false),error=ref('')
onMounted(async()=>{try{profile.value=await api('/profile');name.value=profile.value!.display_name;email.value=profile.value!.email;phone.value=profile.value!.phone}catch(e){error.value=(e as Error).message}})
async function save(password=false){busy.value=true;error.value='';try{if(password){if(newPassword.value!==confirm.value)throw new Error('两次新密码输入不一致');await post('/profile/password',{currentPassword:currentPassword.value,newPassword:newPassword.value})}else await put('/profile',{name:name.value,email:email.value,phone:phone.value,version:profile.value!.version});currentPassword.value='';newPassword.value='';confirm.value='';await csrf();emit('signedOut',password?'密码已更新，请使用新密码登录':'个人资料已保存，请重新登录')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="feature-grid"><section class="panel feature-panel"><h2>个人资料</h2><p class="muted">姓名和联系方式由你维护，部门与角色由管理员分配。</p><form v-if="profile" @submit.prevent="save()"><div class="profile-ident"><strong>{{profile.username}}</strong><span>{{profile.department}} · {{roleNames[profile.role]||profile.role}}</span></div><label class="field-block">姓名<input v-model="name" maxlength="64" required/></label><label class="field-block">邮箱<input v-model="email" maxlength="160" type="email"/></label><label class="field-block">联系电话<input v-model="phone" maxlength="32" type="tel"/></label><p class="small-copy muted">保存后已有登录会失效，请重新登录。</p><button class="btn primary" :disabled="busy">保存个人资料</button></form></section><section class="panel feature-panel"><h2>修改登录密码</h2><p class="muted">密码至少 12 个字符，修改后所有旧登录失效。</p><form @submit.prevent="save(true)"><label class="field-block">当前密码<input v-model="currentPassword" type="password" autocomplete="current-password" required maxlength="256"/></label><label class="field-block">新密码<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="64" required/></label><label class="field-block">确认新密码<input v-model="confirm" type="password" autocomplete="new-password" minlength="12" maxlength="64" required/></label><button class="btn primary" :disabled="busy">修改密码并退出登录</button></form></section><p v-if="error" class="form-error" role="alert">{{error}}</p></div></template>
